    public static function svg(string $name, int $size = 24, string $class = ''): string
    {
        $inner = self::ICONS[$name] ?? self::ICONS['code'];
        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" width="%1$d" height="%1$d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-%2$s %3$s" aria-hidden="true">%4$s</svg>',
            $size,
            htmlspecialchars($name, ENT_QUOTES),
            htmlspecialchars($class, ENT_QUOTES),
            $inner
        );
    }
